L[". Unlock its window to drag and resize it, or place it in the HUD Editor."] = ". Разблокируйте окно, чтобы перетаскивать и менять размер, или разместите его в редакторе HUD."
L["... and %d more"] = "... и еще %d"
L["/copy puts the text of whatever is under your cursor in a box you can copy from. /copy followed by a frame name copies that frame's text instead."] = "/copy помещает текст элемента под курсором в поле, откуда его можно скопировать. /copy с именем фрейма копирует текст этого фрейма."
L["/nf ab <name>: imports a saved action bar set; /nf ab lists them"] = "/nf ab <name>: импорт сохраненного набора панелей; /nf ab выводит их список"
L["/nf badges id: your badge claim code"] = "/nf badges id: ваш код получения значка"
L["/nf bars save, restore, test or delete <name>: your action bar sets; /nf bars list lists them"] = "/nf bars save, restore, test или delete <name>: ваши наборы панелей; /nf bars list выводит их список"
L["/nf lockouts: your raid and dungeon lockouts"] = "/nf lockouts: ваши сохранения рейдов и подземелий"
L["/nf move (or /nf hud): opens or closes the HUD Editor"] = "/nf move (или /nf hud): открывает или закрывает редактор HUD"
L["/nf quiz: the WoW quiz"] = "/nf quiz: викторина по WoW"
L["/nf ranks: higher ranks to put on your bars"] = "/nf ranks: более высокие ранги для ваших панелей"
L["/nf junk: the Junk List"] = "/nf junk: список хлама"
L["/nf trainer: a waypoint to your nearest class trainer"] = "/nf trainer: путевая точка к ближайшему учителю класса"
L["/nf xp start, pause or reset: the XP ticker"] = "/nf xp start, pause или reset: счетчик опыта"
L["/nf: opens the settings"] = "/nf: открывает настройки"
L["/nfquests (or /nfcompleto): the Quest List, in Discovery"] = "/nfquests (или /nfcompleto): список заданий в разделе «Открытия»"
L["0 keeps it up until you close it."] = "0 оставляет его, пока вы его не закроете."
L["1 %s is worth %g to %s."] = "1 %s стоит %g для %s."
L["1 book"] = "1 книга"
L["1 consumable"] = "1 расходуемый предмет"
L["1 consumable watched"] = "1 расходуемый предмет отслеживается"
