L["1 minute"] = "1 минута"
L["1 paladin in your group"] = "1 паладин в группе"
L["1 player has their own blessing"] = "1 игрок со своим благословением"
L["1 profile on this account"] = "1 профиль на этой учетной записи"
L["1 raid"] = "1 рейд"
L["1 runs Naowh Forever"] = "Naowh Forever у 1"
L["1 setting changed from its default"] = "1 настройка изменена по сравнению со стандартной"
L["1 spell"] = "1 заклинание"
L["1 Unspent Talent Point"] = "1 нераспределенное очко таланта"
L["1. PICK YOUR BARS"] = "1. ВЫБЕРИТЕ ПАНЕЛИ"
L["100%  (default)"] = "100%  (по умолчанию)"
L["100%, native resolution"] = "100%, родное разрешение"
L["12-hour clock"] = "12-часовой формат"
L["16x Anisotropic"] = "Анизотропная 16x"
L["2. ALSO KEEP"] = "2. ТАКЖЕ СОХРАНИТЬ"
L["24-Hour Clock"] = "24-часовой формат"
L["24-hour clock"] = "24-часовой формат"
L["3. NAME AND SAVE"] = "3. НАЗОВИТЕ И СОХРАНИТЕ"
L["30, while the game is not in focus"] = "30, когда игра не в фокусе"
L[": copy ID or Wowhead link"] = ": копировать ID или ссылку Wowhead"
L[": mail expiring soon on "] = ": скоро истекает почта у "
L["; buys at vendors"] = "; покупка у торговцев"
L["<AFK>"] = "<Отошел>"
L["<DND>"] = "<Не беспокоить>"
L["[Where?]"] = "[Где?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "/thank всем вокруг, когда игра не может назвать заклинателя."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Ссылка [Где?] после шепота от игрока, чья зона неизвестна. Щелчок выполняет /who и выводит его зону; следующие сообщения будут с пометкой."
L["A banner and a sound when one of them joins your group."] = "Баннер и звук, когда один из них вступает в вашу группу."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Полоса на уровне угрозы, при котором вы перехватите агро, чтобы разрыв был хорошо виден."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Полоса ударов вашей цели, перезапускаемая каждым физическим ударом по вам, пока вы ее цель, и сокращаемая при парировании. Это оценка: игра не сообщает, кто и чем вас ударил, поэтому другие атакующие, физические приемы и тики кровотечения тоже ее перезапускают."
L["A bar left out is not touched by an import."] = "Неотмеченная панель не затрагивается импортом."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Полоса для каждого участника группы с уровнем и прогрессом по нему. Все участники с Naowh Forever делятся опытом даже при выключенной настройке; у остальных виден уровень. Обновления ждут конца боя. Переместите ее в редакторе HUD."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Полоса с названием, стрелкой поворота и расстоянием, пока задана путевая точка."
L["A batch of ten, four done, as it shows while you craft."] = "Партия из десяти, четыре готово, как при создании."
L["A black outline round the clock."] = "Черный контур вокруг часов."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Черный контур вокруг показателей FPS / MS и счетчиков вместо мягкой тени."
L["A black outline round the text, in place of the soft shadow."] = "Черный контур вокруг текста вместо мягкой тени."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Кнопка на каждый комплект: щелчок надевает, Shift-щелчок сохраняет в него надетое, Ctrl-щелчок переименовывает, правый щелчок меняет значок, + сохраняет новый. Надетый комплект обведен. Переместите в редакторе HUD."
L["A button that flags or unflags you for PvP, showing which you are."] = "Кнопка, которая включает или выключает режим PvP и показывает текущее состояние."
L["A campfire in range and Camp Benefits about to run out."] = "Рядом костер, и бонусы лагеря скоро закончатся."
L["A campfire in range and no Camp Benefits."] = "Рядом костер, а бонусов лагеря нет."
L["A campfire is in range"] = "Рядом костер"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Карточка под текстом, мягкое темное затенение или ничего."
L["A card over the pin with what it is and how far."] = "Карточка над меткой с описанием и расстоянием."
L["A cast part way through, swept around the ring."] = "Частичное применение, развернутое по кольцу."
L["A cast someone interrupted, held for the fade time."] = "Прерванное кем-то заклинание, удерживаемое на время исчезновения."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Заклинание, пока ваше прерывание восстанавливается, с отметкой его готовности."
L["A cast while your interrupt is ready."] = "Заклинание, когда ваше прерывание готово."
L["A cast you cannot interrupt, with its shield."] = "Заклинание, которое нельзя прервать, со щитом."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Персонаж появится здесь после входа им с включенным учетом подземелий. «Отслеживать альтов» показывает остальных: отдых и прочность на момент последнего входа этим персонажем."
L["A choice among its rewards: pick this one."] = "Выбор среди наград: возьмите эту."
L["A command name can only use letters, numbers and underscores."] = "Имя команды может содержать только буквы, цифры и подчеркивания."
L["A consumable or personal buff with less time than this left counts as missing."] = "Расходуемый предмет или личный бафф с меньшим остатком времени считается отсутствующим."
L["A crosshair at the middle of your screen."] = "Прицел в центре экрана."
L["A cup beside a healer who is drinking."] = "Чашка рядом с пьющим лекарем."
L["A custom command can't reload. Type /reload."] = "Своя команда не может перезагрузить UI. Введите /reload."
L["A dark or light fill and edge behind each line, or none."] = "Темная или светлая заливка и край за каждой строкой или ничего."
L["A dark panel behind the icons."] = "Темная панель за значками."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Дверь у каждого входа в подземелье и рейд на карте мира, со сторон, указанных в журнале. Наведите для уровней, щелкните для путевой точки."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Точка на ячейке, для которой есть лучшее чарование для вашего уровня: наведите для совета, щелкните, чтобы спросить в канале торговли."
L["A fading trail behind the cursor."] = "Исчезающий след за курсором."
L["A few quick steps for %s only, its own modules included."] = "Несколько быстрых шагов только для %s, включая его модули."
L["A game that opens when a flight starts and closes when you land."] = "Игра, которая открывается в начале полета и закрывается при приземлении."
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "Игра, чтобы скоротать полет: викторина или тир. Закрывается при приземлении."
L["A gear set called %s already exists."] = "Комплект экипировки %s уже существует."
L["A glow on the moving edge of the fill."] = "Свечение на движущемся краю заливки."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Скрытая цепочка заданий по всему Азероту: щелкайте по предметам в мире по очереди. Дает много опыта и завершается Уютным спальным мешком; отдых в нем дает бонус к опыту."
L["A key that opens Group Inspect."] = "Клавиша, открывающая осмотр группы."
L["A key that shows a boss's loot at your cursor."] = "Клавиша, показывающая добычу босса у курсора."
L["A key that uses this item."] = "Клавиша, использующая этот предмет."
L["A later point needs it. "] = "Нужно для следующего очка. "
L["A later step."] = "Следующий шаг."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Строка для каждого сданного задания с полученными опытом и деньгами. Предметы-награды выводятся отдельными строками."
L["A line for every reputation gain, from quests and kills alike."] = "Строка для каждого прироста репутации, от заданий и убийств."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Строка с опытом за каждое убийство. Опыт за задание в строке самого задания."
L["A line from the pin down to a map pin's or corpse's spot."] = "Линия от метки к точке на карте или к трупу."
L["A line in chat with the item's link."] = "Строка в чате со ссылкой на предмет."
L["A line in their color on their player tooltip."] = "Строка его цветом в подсказке игрока."
L["A line to share them with."] = "Строка, чтобы ими поделиться."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Строка под ID с клавишами для копирования (Ctrl-Shift-C: копировать ID или ссылку Wowhead). Если выключено, сочетание работает, просто строка не показывается."
L["A look you do not have yet|r"] = "Облик, которого у вас еще нет|r"
L["a macro made on this character"] = "макрос, созданный на этом персонаже"
L["A macro this character does not have yet: the import makes it."] = "Макроса еще нет у этого персонажа: импорт его создаст."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Кнопка у миникарты, открывающая %s. /nf%s делает то же самое, ее можно поставить и на верхнюю панель. Сохраняется для этого компьютера."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Строка весов Naowh или экспорт EP из WoWSims (в WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Строка весов Naowh или экспорт EP из WoWSims."
L["A new session, before any experience."] = "Новый сеанс, до получения опыта."
L["A parry by your target took 40% off its swing."] = "Парирование вашей цели сократило ее удар на 40%."
L["A party of five, a card each."] = "Группа из пяти, по карточке на каждого."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "Рейтинг игрока в его подсказке. Игроки с Naowh Forever делятся своим; у остальных он считается по экипировке при наведении, в радиусе осмотра и вне боя."
L["A profile"] = "Профиль"
L["a quest"] = "задание"
L["A quest reward for the other faction; try the Auction House."] = "Награда за задание другой фракции; поищите на аукционе."
L["A raid for %d players"] = "Рейд на %d игроков"
L["A raid, a row each."] = "Рейд, по строке на каждого."
L["A rare someone else is fighting."] = "Редкий противник, с которым сражается кто-то другой."
L["A rare you have killed before."] = "Редкий противник, которого вы уже убивали."
L["A rare you have not killed yet."] = "Редкий противник, которого вы еще не убивали."
L["A reward from the quest "] = "Награда за задание "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Кольцо вокруг курсора, чтобы не терять его в суматохе боя, с разверткой глобального восстановления и заклинаний."
L["A round in progress."] = "Раунд в процессе."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Ряд значков отсутствующих баффов от еды, настоев, эликсиров и свитков, вашего классового баффа и классовых баффов, которых нет в группе. Только вне боя: в бою игра скрывает ваши баффы от аддонов, поэтому значки остаются прежними. Наведите на значок, чтобы выбрать предмет для использования. Переместите их в редакторе HUD."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Текущее золото в час рядом с новой строкой, с учетом денег и стоимости предметов с первой добычи за сеанс."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Кнопка «Сканировать цены» на аукционе. Читает все лоты и сохраняет минимальный выкуп для каждого предмета для этого игрового мира и фракции. Blizzard разрешает полное сканирование раз в 15 минут."
L["A junk icon on the bag slot of each item marked as junk."] = "Значок хлама на ячейке сумки у каждого предмета, помеченного как хлам."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Вторая панель для фокуса, чтобы следить за Ошеломлением или Превращением на одном противнике, пока сражаетесь с другим."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Комплект, который надевается сам, когда вы верхом или отдыхаете, а потом возвращается прежний."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Игра-стрелялка для полетов: щелкайте по расам другой фракции как можно быстрее."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Короткая вспышка текста при входе в бой и выходе из него. Переместите ее в редакторе HUD."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Небольшая панель со следующим визитом к учителю и вашим золотом на время прокачки. Перемещается перетаскиванием."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Небольшая полоса здоровья второго танка в группе, видна, пока вы танкуете: роль танка, облик медведя, оборонительная стойка или Праведное неистовство. Второй танк тот, у кого роль танка или назначение главного танка в рейде. Щелкните, чтобы взять его в цель. Изменения в бою применяются после боя. Переместите в редакторе HUD."
L["A soft glow around Naowh's arrow."] = "Мягкое свечение вокруг стрелки Naowh."
L["A soft glow beside each icon."] = "Мягкое свечение рядом с каждым значком."
L["A soft glow round it in your accent color."] = "Мягкое свечение цветом акцента."
L["A soft glow round it in your rank's color."] = "Мягкое свечение цветом вашего ранга."
L["A soft ring pulses around each target."] = "Вокруг каждой цели пульсирует мягкое кольцо."
L["a sound to refresh"] = "звук для обновления"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Звук или текст речи вслух в начале каждого заклинания."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Звук или текст речи вслух. Синтез речи может подтормаживать на некоторых ПК, так как игра ждет, пока Windows его произнесет; звук ничего не стоит."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Заклинание, которое импорт не смог поставить, потому что вы его еще не знаете, попадет в сохраненную ячейку при изучении, если вы ничего туда не поставили."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Кнопка «Сложить» на карточке, когда неполные стопки предмета можно объединить."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Звезда на карте мира для каждого неубитого редкого противника в самом вероятном месте. Наведите, чтобы увидеть его и добычу, другие места появления и маршрут патруля; щелчок ставит путевую точку, правый щелчок оставляет места и маршрут на карте."
L["A string to share it with."] = "Строка, чтобы им поделиться."
L["A supporter"] = "Поддерживающий"
L["A team member"] = "Участник команды"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Текст на полосе: щелкните по нему в предпросмотре, чтобы изменить. Каждый текст показывается в одном месте на полосе: выбор уже показанного переносит его сюда."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Отметка на полосе, где ваше прерывание восстановится. Скрыта, пока оно готово."
L["A title bar naming the mob the threat is on."] = "Заголовок с именем существа, на котором угроза."
L["A trained spell drops into its saved slot."] = "Изученное заклинание попадает в сохраненную ячейку."
L["a vendor sells the formula"] = "формулу продает торговец"
L["A warning when a rare is near"] = "Предупреждение о редком противнике рядом"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Предупреждение, когда рядом редкий противник: появляется его индикатор здоровья, вы наводите на него курсор или берете в цель. Карточка с портретом: правый щелчок закрывает, метка ставит путевую точку к нему. Переместите в редакторе HUD."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Предупреждение, когда у охотника или чернокнижника нет питомца. Чернокнижник, принесший демона в жертву, не беспокоится. Переместите в редакторе HUD."
L["A word of your own on the icon."] = "Ваше слово на значке."
L["A world drop from %d kinds of mob"] = "Добыча в мире с %d видов существ"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Викторина по WoW для костров и полетов или в любое время по /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Желтый ! на карте мира у каждого, кто выдает задание, которое еще дает опыт. Наведите для списка заданий; щелкните для путевой точки."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Зона старше этого больше не показывается, так как игрок, скорее всего, ушел."
L["Abandon %s?"] = "Отказаться от задания %s?"
L["Abilities"] = "Способности"
L["about "] = "около "
L["about %d:%02d"] = "около %d:%02d"
L["About %s at your last scan%s%s"] = "Около %s при последнем сканировании%s%s"
L["About %s spent"] = "Потрачено около %s"
L["About a minute."] = "Около минуты."
L["Above"] = "Выше"
L["Acc."] = "Точн."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Акцент: нет классового благословения. Светлее: заканчивается. Темнее: только у игроков со своим."
L["Accept Quests"] = "Принимать задания"
L["Accept Shared Dungeon Quests"] = "Принимать общие задания подземелий"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Принимает задание сразу при открытии его текста. Используйте модификатор, чтобы сначала прочитать."
L["Accepts dungeon quests your group shares with you straight away."] = "Сразу принимает задания подземелий, которыми делится группа."
L["Accepts shared quests"] = "Принимает общие задания"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Принимает всплывающее окно: призыв, воскрешение, приглашение в группу."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Принимает, сдает задания и делится ими, запоминает награду, сохраненную для задания. Модификатор пропускает или запускает их, как указано в «Действие модификатора»."
L["Account"] = "Учетная запись"
L["Account "] = "Учетная запись "
L["Account macros"] = "Макросы учетной записи"
L["Account this hour: %d of %d"] = "Учетная запись за час: %d из %d"
L["Accuracy"] = "Точность"
L["Action Bars is switched off."] = "Панели команд выключены."
L["Action Bars' own window, with your class's saved sets."] = "Собственное окно панелей команд с сохраненными наборами вашего класса."
L["Active"] = "Активно"
L["Activity Bar"] = "Полоса активности"
