L["Activity Bar Height"] = "Высота полосы активности"
L["Add %d item to your junk list: %s%s?"] = "Добавить %d предмет в список хлама: %s%s?"
L["Add %d items to your junk list: %s%s?"] = "Добавить предметы (%d) в список хлама: %s%s?"
L["Add %d macro as character macros?%s"] = "Добавить %d макрос как макрос персонажа?%s"
L["Add %d macros as character macros?%s"] = "Добавить макросы (%d) как макросы персонажа?%s"
L["Add %s"] = "Добавить %s"
L["Add %s (%d items) as a new BiS list?"] = "Добавить %s (предметов: %d) как новый список BiS?"
L["Add %s to the Consumable Bar?"] = "Добавить %s на панель расходуемых?"
L["Add a backup pick"] = "Добавить запасной вариант"
L["Add a Button"] = "Добавить кнопку"
L["Add a stat"] = "Добавить характеристику"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Добавьте ID предмета или импортируйте список. Еда учитывает любой бафф «Сытость», другие предметы свой бафф; ID заклинаний баффов добавляйте только для предмета, дающего другой бафф. Ничего не добавляется автоматически. Наведите на напоминание, чтобы выбрать настроенный предмет из сумок. Напоминания приостанавливаются в бою; меню предметов работают вне боя. Когда и где их показывать, задается в AuraBuffs > Настройки."
L["Add consumables, put them in order, and set each one up."] = "Добавьте расходуемые предметы, расставьте их по порядку и настройте каждый."
L["Add Items"] = "Добавить предметы"
L["Add Latency"] = "Добавлять задержку"
L["Add macros someone shared with you."] = "Добавьте макросы, которыми с вами поделились."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Добавляйте и удаляйте свои команды, включайте и выключайте каждую или восстановите стандартные."
L["Add Slash Command"] = "Добавить команду"
L["Add the %s build %s (%d points)?"] = "Добавить сборку %s %s (очков: %d)?"
L["Add the consumables to watch in the AuraBuffs window."] = "Добавьте расходуемые предметы для отслеживания в окне AuraBuffs."
L["Add Themes to RestedXP"] = "Добавить темы в RestedXP"
L["Add to BiS List"] = "Добавить в список BiS"
L["Add to Shopping List"] = "Добавить в список покупок"
L["Add to the Left Side"] = "Добавить слева"
L["Add to the Right Side"] = "Добавить справа"
L["Add your consumables, put them in order, set each one up."] = "Добавьте расходуемые предметы, расставьте по порядку, настройте каждый."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Добавьте свои строки в макросы сумок. Они сохраняются после предмета, что бы ни лежало в сумках."
L["Added %d consumable to the Consumable Bar."] = "Добавлен %d расходуемый предмет на панель расходуемых."
L["Added %d consumables to the Consumable Bar."] = "Добавлено расходуемых предметов на панель: %d."
L["Added %d consumables; %d were already listed or past the %d limit."] = "Добавлено расходуемых: %d; %d уже были в списке или превысили лимит %d."
L["Added %d of %d: %s."] = "Добавлено %d из %d: %s."
L["Added %d."] = "Добавлено: %d."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "%s добавлен этому персонажу. Перетащите его на панель из окна макросов (/macro)."
L["Added %s to your BiS %s as #%d."] = "%s добавлен в ваш BiS %s под номером %d."
L["Added %s to your BiS %s."] = "%s добавлен в ваш BiS %s."
L["Added next to your Library, never over it"] = "Добавляется рядом с вашей библиотекой, не поверх нее"
L["Added next to your own lists, never over them"] = "Добавляется рядом с вашими списками, не поверх них"
L["Added next to your saved builds"] = "Добавляется рядом с вашими сохраненными сборками"
L["Adding Items"] = "Добавление предметов"
L["Addon Font"] = "Шрифт аддона"
L["Addon List"] = "Список аддонов"
L["Addon Memory"] = "Память аддонов"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Добавляет «- [1] + Добавить в список» под реагентами рецепта: материалы, которые купила бы кнопка «Купить на аукционе» для такого числа изделий, попадают в список покупок откуда угодно. На аукционе список показывается рядом: «Проверить цены» узнает цену каждого и предупреждает красным, если она намного выше прошлого сканирования, затем «Купить все» проходит по списку по одному материалу, покупая каждый только после подтверждения итоговой цены. Если материал дешевле сделать из частей, например слиток из руды, покупаются части."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Добавляет столбец «Сумки» к реагентам выбранного рецепта: сколько каждого у вас с собой."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Добавляет столбец «Банк» к реагентам выбранного рецепта: сколько каждого в банке."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Добавляет во всплывающее окно кнопку, которая заменяет все низшие ранги на панелях высшим известным. Панели клавиатуры и контроллера получают ту же ячейку. Правый щелчок по заклинанию во всплывающем окне сохраняет его низшие ранги для понижения ранга. Замена рангов только вне боя."
L["Adds a Land button to come down at the next stop on the way."] = "Добавляет кнопку «Приземлиться», чтобы сойти на следующей остановке по пути."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Добавляет строку, отмечающую ячейки, где чары отсутствуют или отличаются от захваченных через «Захватить текущие чары». Наведите для подробностей."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Добавляет в подсказку заклинания с маной исцеление или урон за ед. маны и в секунду."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Добавляет второе, оранжевое число рядом с каждым рецептом: сколько можно сделать, купив реагенты у торговцев, например слабый флюс или грубую нить. Тогда в реагентах рецепта указано, сколько каждого купить."
L["Adds how long the visit lasted."] = "Добавляет длительность визита."
L["Adds target and focus switching to the meter's title bar."] = "Добавляет переключение цели и фокуса в заголовок измерителя."
L["Adds the average experience here."] = "Добавляет средний опыт здесь."
L["Adds the coins looted."] = "Добавляет добытые монеты."
L["Adds the consumables in your bags that are not on the bar yet."] = "Добавляет расходуемые предметы из сумок, которых еще нет на панели."
L["Adds the deaths."] = "Добавляет смерти."
L["Adds the experience gained."] = "Добавляет полученный опыт."
L["Adds the materials for one more craft."] = "Добавляет материалы еще на одно изделие."
L["Adds the Naowh themes to RestedXP's theme list."] = "Добавляет темы Naowh в список тем RestedXP."
L["Adds the reputation gained."] = "Добавляет полученную репутацию."
L["Adds the visits at this level."] = "Добавляет визиты на этом уровне."
L["Adds the visits until you level."] = "Добавляет визиты до нового уровня."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "Учитывает ваш бонус к исцелению или урону от заклинаний; если выключено, показываются базовые значения."
L["Advanced"] = "Дополнительно"
L["Advanced (CMAA2)"] = "Расширенное (CMAA2)"
L["Advanced Combat Logging"] = "Расширенный журнал боя"
