L["After each fight longer than 15 seconds, how long you spent neither casting nor on the global cooldown, in chat."] = "После каждого боя дольше 15 секунд выводит в чат, сколько времени вы не произносили заклинания и не были на глобальном восстановлении."
L["after the 5% cut"] = "после 5% комиссии"
L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "После визита к учителю небольшое окно перечисляет только что изученные способности. Способности из книги или задания появляются чуть позже. Перетащите их из окна на панели."
