L["Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them, in place of the cast bar that fills for every craft. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer."] = "Создание нескольких предметов сразу («Создать все» или «Создать» с количеством) показывает одну полосу на всю партию, как у таймера полета: рецепт, сколько готово и сколько времени осталось на все, вместо полосы применения для каждого изделия. Она стоит на месте таймера полета, ведь в полете никто не создает: перемещайте ее в редакторе HUD как таймер полета."
