L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "Название или значок каждого класса под кнопкой или рядом с ней, если панель вертикальная."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Каждый визит в подземелье или рейд при включенном учете подземелий: сколько вы пробыли внутри, добытые монеты и полученный опыт. Полученная репутация указана под визитом. Возвращение к той же группе в течение часа до сброса продолжает визит, и время снаружи не считается. Другие персонажи сохраняются и видны здесь при включенном «Отслеживать альтов». Ремонт и продажи торговцам не учитываются. Старые визиты удаляются с конца списка."
L["Each line fades out after %ss."] = "Каждая строка исчезает через %s с."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Каждый из них макрос учетной записи. Поставьте его на панель один раз, и он будет обновляться сам: добудьте зелье получше, сотворите свежую еду или подберите бинты, и макрос перепишется на лучшее, что у вас есть.\n\nИгра не дает менять макросы в бою, поэтому изменение в бою ждет его окончания."
L["Each point of the trail in a color of its own."] = "Каждая точка следа своего цвета."
