L["Everything you loot pops up on screen with its icon, amount and value, stacking in your chosen direction and fading out. Hover a line for the item's tooltip. Move it in the HUD Editor."] = "Вся добыча появляется на экране со значком, количеством и стоимостью, складываясь в выбранном направлении и исчезая. Наведите на строку для подсказки предмета. Переместите в редакторе HUD."
