L["How big the entrance icons are. They are largest on a zone's map, smaller on a continent's and the world's."] = "Размер значков входов. Крупнее всего на карте зоны, меньше на карте континента и мира."
L["How big the on-screen alert is."] = "Размер оповещения на экране."
L["How big the pins are on the map."] = "Размер меток на карте."
