L["Onboarding"] = "Знакомство"
L["Once Per Player Every"] = "Один раз на игрока каждые"
L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "После сканирования аукциона («Сканировать цены») выбранный рецепт показывает стоимость покупки реагентов, цену продажи предмета и прибыль после 5% комиссии аукциона. Каждый реагент оценивается по самой низкой цене: цене торговца, если вы видели, что он его продает, иначе по минимальному выкупу при последнем сканировании. Снимите отметку с реагента, который у вас уже есть, чтобы исключить его из стоимости всех рецептов с ним. Наведите на строки для подробностей."
L["One addon"] = "Один аддон"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "По полосе на оружие, по собственному событию удара игры, поэтому ускорение при парировании, сброс удара и скорость всегда верны. Переместите их в редакторе HUD."
L["One Fewer"] = "На одно меньше"
L["One item per click: the game needs a click for every disenchant."] = "Один предмет за щелчок: игре нужен щелчок для каждого распыления."
L["One More"] = "Еще одно"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Одно число для экипировки персонажа по шкале уровня предметов: 26,4 означает экипировку, равную комплекту эпических вещей 26 уровня. Ваше всегда видно на кукле в списке BiS."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Одно сообщение шепотом на строку, выбирается случайно; {buff} и {name} подставляются."
L["Online"] = "В сети"
L["Only %d listed right now."] = "Сейчас выставлено только %d."
L["Only buffs a dispel or purge can take off."] = "Только баффы, которые можно снять рассеиванием или очищением."
L["Only Buffs I Can Cast"] = "Только баффы, которые я могу наложить"
L["Only count food and drink whose required level is within this range."] = "Учитывать только еду и питье с требуемым уровнем в этом диапазоне."
L["Only If I Carry One"] = "Только если есть с собой"
L["Only In a Group"] = "Только в группе"
L["Only In Combat"] = "Только в бою"
L["Only In Dungeons & Raids"] = "Только в подземельях и рейдах"
L["Only In Instances"] = "Только в подземельях"
L["Only in its window"] = "Только в его окне"
L["Only Magic Buffs"] = "Только магические баффы"
L["Only quest chains: the first quest of each one, and the next step of those you are on."] = "Только цепочки заданий: первое задание каждой и следующий шаг тех, что вы выполняете."
L["Only the gear that beats what you wear: a higher pick on your BiS list, or a higher item level you can wear."] = "Только экипировка лучше надетой: выше в вашем списке BiS или с более высоким уровнем предмета, который вы можете надеть."
L["Only the group leader can disband the group."] = "Только лидер группы может распустить группу."
L["Only the group leader or an assistant can plan every paladin's blessings."] = "Только лидер группы или помощник может планировать благословения всех паладинов."
L["Only the loot you still need from your BiS list: higher on it than what you wear, and not in your bags or bank."] = "Только добыча, которая вам еще нужна из списка BiS: выше в нем, чем надетое, и не в сумках или банке."
L["Only the loot your class can use. Off, the rest is listed faded."] = "Только добыча, которую может использовать ваш класс. Если выключено, остальное показано бледным."
