L["Press it to open or close the Dungeon Journal."] = "Нажмите, чтобы открыть или закрыть путеводитель по подземельям."
L["Press it to open or close the Quest List. Shift-L unless something else had it."] = "Нажмите, чтобы открыть или закрыть список заданий. Shift-L, если она не занята."
L["Press something still on cooldown and its icon, name and time left show by your mouse."] = "Нажмите то, что еще восстанавливается, и значок, название и оставшееся время появятся у курсора."
L["Press this key to open Group Inspect, and again to close it."] = "Нажмите эту клавишу, чтобы открыть осмотр группы, и еще раз, чтобы закрыть."
L["Press this key to open the BiS List, and again to close it."] = "Нажмите эту клавишу, чтобы открыть список BiS, и еще раз, чтобы закрыть."
