L["Prices from your own scans of the auction house, kept for each realm and faction. Item tooltips, Bag Space and the Loot Feed can use them."] = "Цены из ваших сканирований аукциона, для каждого мира и фракции. Их могут использовать подсказки предметов, «Место в сумках» и лента добычи."
L["Prices from your trainer"] = "Цены вашего учителя"
