L["Priests"] = "Жрецы"
L["Primary Profession"] = "Основная профессия"
L["Prints a summary when you leave a dungeon."] = "Выводит сводку при выходе из подземелья."
L["Prints in your chat when you enter an instance."] = "Пишет в чат при входе в подземелье."
L["Prints the summary in your chat or in the group."] = "Выводит сводку в ваш чат или в группу."
L["Profession Trainers"] = "Учителя профессий"
