L["Protect BiS and Gear Sets"] = "Защищать BiS и комплекты экипировки"
L["Protect Needed Items"] = "Защищать нужные предметы"
L["Pulling Aggro"] = "Перехват агро"
L["Pulsing Targets"] = "Пульсирующие цели"
L["Put back every setting this page has changed?"] = "Вернуть все настройки, измененные на этой странице?"
L["put down what you are holding first."] = "сначала положите то, что держите."
L["Put every %s weight back to the defaults?"] = "Вернуть все веса для %s к стандартным?"
L["Put every setting back to how it was before the onboarding?"] = "Вернуть все настройки к состоянию до знакомства?"
L["Put every setting in this profile back to its default."] = "Вернуть все настройки этого профиля к стандартным."
L["Put on in cities and inns, and taken off again when you leave."] = "Надевается в городах и тавернах и снимается при уходе."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "Надевается, когда вы верхом, а прежний комплект возвращается после спешивания."
L["Put the XP Bar colors back to their defaults?"] = "Вернуть цвета полосы опыта к стандартным?"
L["Put the XP Bar's size and texts back to their defaults?"] = "Вернуть размер и тексты полосы опыта к стандартным?"
L["Put this bar back in"] = "Вернуть эту панель"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "Ставит рейдовую метку на фокус. Повторное нажатие макроса на том же фокусе снимает метку."
L["Puts back every setting this page has changed, to the value you had before."] = "Возвращает все настройки, измененные на этой странице, к прежним значениям."
L["Puts back everything changed since the HUD Editor opened."] = "Возвращает все изменения с момента открытия редактора HUD."
L["Puts back the last change. Ctrl + Z."] = "Отменяет последнее изменение. Ctrl + Z."
L["Puts both back where the game shows them."] = "Возвращает оба туда, где их показывает игра."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Возвращает все веса этой специализации к стандартным. Сначала спрашивает."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Ставит первыми еду, питье и зелья на 10 и более уровней ниже вас, отмеченные часами."
L["Puts the bar back on the screen."] = "Возвращает панель на экран."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Возвращает кнопки панели как было: путеводитель по подземельям и «Открытия» слева, список BiS и планировщик обучения справа."
L["Puts the card back above the middle of the screen, where it starts."] = "Возвращает карточку на исходное место над центром экрана."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Ставит самый дешевый предмет в дальний конец строки, а не рядом с якорем."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Берет самый дешевый предмет на курсор, чтобы выбросить или продать."
L["Puts the count just past the icon's edge."] = "Ставит число сразу за краем значка."
L["Puts the key just past the icon's edge."] = "Ставит клавишу сразу за краем значка."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Добавляет в список покупок материалы на указанное число изделий: все отмеченные реагенты, которых нет у торговцев, без учета содержимого сумок. Снимите отметку с реагента, чтобы пропустить. На аукционе список показывается рядом, чтобы проверить цены и купить все."
L["Puts the popup back where it first showed."] = "Возвращает окно туда, где оно появилось впервые."
L["Puts the quiz back where it first opened."] = "Возвращает викторину туда, где она открылась впервые."
L["Puts the text just past the icon's edge."] = "Ставит текст сразу за краем значка."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Добавляет этот рецепт в заказ справа с числом изделий и вашими материалами. Изменения здесь после добавления меняют и заказ. До %d рецептов в заказе."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Надевает этот комплект. В бою он наденется после боя."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Применяет одну из настроек Naowh или снова проводит вас по ним."
