L["Size of this options window and the editors it opens, as a percentage. This window never grows past your screen, so above that size a higher setting only enlarges the editors.|n|nSaved for this computer instead of in the profile, so switching profile leaves it alone."] = "Размер этого окна параметров и открываемых им редакторов в процентах. Окно никогда не выходит за пределы экрана, поэтому выше этого размера увеличиваются только редакторы.|n|nСохраняется для этого компьютера, а не в профиле, поэтому смена профиля его не меняет."
