L["That talent is not in this class's tree."] = "Этого таланта нет в дереве этого класса."
L["The Aim Trainer can't open in combat."] = "Тир нельзя открыть в бою."
L["The Aim Trainer is off. Turn it on in /nf, QoL, Travel."] = "Тир выключен. Включите его в /nf, Удобства, Путешествие."
L["The arrows or shot in your ammo slot."] = "Стрелы или пули в ячейке боеприпасов."
L["The auction house gave no final price."] = "Аукцион не сообщил итоговую цену."
