L["them all."] = "их все."
L["Theme"] = "Тема"
L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "Готовые темы для окон и HUD аддона, а также вариант «Свое» для ваших цветов. Если текст плохо читается, выберите Naowh (по умолчанию). Сохраняется для этого компьютера.|n|nВступит в силу после /reload."
