L["What it shows as you enter combat."] = "Что показывается при входе в бой."
L["What it shows as you leave combat."] = "Что показывается при выходе из боя."
L["What Lines Show"] = "Что показывают строки"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Что окно профессий Naowh добавляет к каждому рецепту: неизученные рецепты, следующий ранг и сколько у вас каждого реагента."
L["What opens when a flight starts; Off hides the Games button."] = "Что открывается в начале полета; «Выкл.» скрывает кнопку игр."
L["What Rows Show"] = "Что показывают строки"
L["What shows while you know a find but track none."] = "Что показывается, пока вы знаете поиск, но ничего не отслеживаете."
L["What the copy card has selected when it opens."] = "Что выделено в карточке копирования при открытии."
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "Что журнал перечисляет у босса. Те же переключатели, что у значка фильтров в заголовке."
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "Сколько стопка стоит на аукционе по последнему сканированию цен или TradeSkillMaster."
L["What the whole stack sells for at a vendor, and each item's price."] = "Сколько вся стопка стоит у торговца и цена каждого предмета."
L["What to train at each level, and its cost."] = "Что изучать на каждом уровне и сколько это стоит."
L["What you can train now and what each level brings."] = "Что можно изучить сейчас и что дает каждый уровень."
L["What you can train now, what each level brings and what it costs."] = "Что можно изучить сейчас, что дает каждый уровень и сколько это стоит."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "Сколько вы платите ремесленнику за это изделие, отправляется с сообщением. Заполнено предлагаемыми чаевыми; введите свои как 2g 50s, 75s или 2.5 (золото). Очистите, чтобы вернуть предложение."
L["What you wear that takes a better enchant for your level."] = "Надетое, для чего есть лучшие чары для вашего уровня."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "Что делает ваша цель в бою: ее короткие баффы и контроль на ней."
L["Wheel"] = "Колесо"
L["Wheel on the rows"] = "Колесо на строках"
L["Wheel: size. Right-click for more."] = "Колесо: размер. Правый щелчок для прочего."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "Колесо: размер текста. Щелкните по строке, чтобы скрыть. Правый щелчок для прочего."
L["When"] = "Когда"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "Когда навык профессии достаточен для следующего ранга (подмастерье, умелец, искусник), баннер под полосой навыка и на ее карточке в обзоре сообщает, что нужно и кто обучает: ближайший учитель, продавец книги или выдающий задание. Нажмите «Путевая точка», чтобы отметить их на карте. При достижении это также один раз пишется в чат; /naowh profrank повторяет."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "Когда предмет из вашего списка разыгрывается или в окне добычи, и снова, когда он ваш. Перемещайте оповещение на экране в редакторе HUD."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "Когда NPC предлагает несколько вариантов, сразу переходит к выполненному заданию для сдачи или к первому предложенному заданию. Работает с двумя параметрами выше."
L["When it is up for a roll or drops."] = "Когда разыгрывается или выпадает."
L["When it is yours."] = "Когда становится вашим."
L["When You Leave"] = "При выходе"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "Когда вы получаете уровень с новыми заклинаниями для изучения, уведомление сообщает их число и стоимость, с кнопками открыть планировщик и поставить путевую точку к ближайшему учителю. Переместите в редакторе HUD."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "При выходе последний сохраненный этим персонажем набор пересохраняется с текущими панелями, макросами и назначениями клавиш."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "Когда вы добираетесь до города или таверны, в центре экрана мигает список того, чего не хватает. Он остается, пока у вас не будет нужного или пока вы не уйдете. Переместите в редакторе HUD."
L["When You Reset"] = "При сбросе"
L["Where"] = "Где"
L["Where %s starts is not known."] = "Неизвестно, где начинается %s."
L["Where do you want to start?"] = "С чего вы хотите начать?"
L["Where it comes from is not recorded yet; try the Auction House."] = "Откуда это берется, пока не записано; попробуйте аукцион."
L["Where It Drops"] = "Где выпадает"
L["Where on the frame the bar sits."] = "Где на фрейме находится полоса."
L["Where to get them"] = "Где их получить"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "Где располагаются расстояние до перехвата агро и число записей: под полосами или между заголовком и полосами."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "Где ваша звезда: в углу значка, перед именем или скрыта."
L["Where? on Whispers"] = "«Где?» в шепоте"
L["Whether a healthstone or a potion comes first."] = "Что идет первым: камень здоровья или зелье."
L["Whether a new mark counts on every character or only this one."] = "Действует ли новая пометка на всех персонажах или только на этом."
L["Whether NF Food leaves drinks to NF Drink."] = "Оставляет ли NF Food питье для NF Drink."
L["Which blessing you give this class: Might, Wisdom, Kings, Salvation or Light."] = "Какое благословение вы даете этому классу: могущества, мудрости, королей, спасения или света."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "Какой контроль показывать, по способности: все ранги и то же заклинание от предметов и существ."
L["Which debuffs show beside crowd control: off until you light them."] = "Какие отрицательные эффекты показывать рядом с контролем: выключены, пока вы их не подсветите."
L["Which guild and title lines show with players' names, saved by the game itself."] = "Какие строки гильдии и званий показываются с именами игроков, сохраняется самой игрой."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "Какие виды расходуемых добавляет «Сканировать сумки» и о каких спрашивает «Спрашивать о добавлении»."
L["Which mana spells get the line."] = "Какие заклинания с маной получают строку."
L["Which modules do you want?"] = "Какие модули вам нужны?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "Какой выбор вызывает оповещение: только ваш BiS, первые два или каждый выбор в списке."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "Что макрос использует первым, если у вас есть оба: камень здоровья или лечебное зелье."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "Пока открыт торговец, кнопка «Купить» под реагентами выбранного рецепта покупает у него одним щелчком все отмеченные реагенты, которые он продает, например грубую нить или слабый флюс, на столько изделий, сколько указано рядом. Общая стоимость показана рядом с кнопкой; наведите на «Купить» для каждого реагента."
L["While flying"] = "В полете"
L["While flying and at the campfire"] = "В полете и у костра"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "Пока в очереди Удар героя, Рассекающий удар, Трепка или Удар ящера, полосы ближнего боя принимают его цвет и название."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "Пока открыт аукцион, кнопка «Купить» под реагентами выбранного рецепта покупает материалы на столько изделий, сколько указано рядом: все отмеченные реагенты, которых нет у торговцев. Сначала показывается цена каждого, а покупка только после нажатия «Подтвердить»."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "Пока открыт аукцион, кнопка «Искать на аукционе» рядом с названием выбранного рецепта ищет создаваемый им предмет. Для неизученных рецептов есть также «Поиск рецепта» для выкройки, чертежа или руководства. Рецепты без предмета, например чары, не получают «Искать на аукционе»."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "Пока открыт аукцион, Shift-щелчок по рецепту или реагенту ищет предмет на аукционе: то, что создает рецепт, или сам реагент. При вводе в чат Shift-щелчок по-прежнему вставляет ссылку."
L["While the mouse is away, with Show On Mouseover on."] = "Пока мышь не над ним, с включенным «Показывать при наведении»."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "Пока вы в группе, делится с остальными каждым заданием, принятым у NPC, если им можно поделиться. Задание, которым поделились с вами, повторно не передается. Модификатор при принятии оставляет его только вам."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "Пока у вас есть книги, метка на том, кто их принимает: библиотекаре или учителе магов."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "Во время произнесения отмечает на полосе правой руки, где закончится заклинание. Метка краснеет, если заклинание еще будет идти, когда подойдет удар."
L["whisper"] = "шепот"
L["Whisper "] = "Шепнуть "
L["Whisper Lines"] = "Строки шепота"
L["Whisper your target"] = "Шепнуть цели"
