L["Whispers thanks when a player gives you a class buff in the open world; turn friendly nameplates on so the game can name them."] = "Благодарит шепотом, когда игрок накладывает на вас классовый бафф в открытом мире; включите индикаторы здоровья союзников, чтобы игра могла назвать его."
L["White: exact, from their Naowh Forever. Grey: added up from their gear."] = "Белый: точно, из их Naowh Forever. Серый: подсчитано по экипировке."
L["Who the cast is aimed at, in their class color."] = "На кого нацелено заклинание, цветом его класса."
L["Whoever holds aggro in one color."] = "Тот, у кого агро, одним цветом."
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "Чей рейтинг показывает выбор. Каждая специализация хранит свой выбор в списке."
