L["Your BiS you do not have yet: where to go next."] = "BiS, которого у вас еще нет: куда идти дальше."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "Звезда BiS на ячейке и знак Forever на том, что ново в Forever."
