L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "Ваши кнопки по обе стороны от часов (по желанию), с FPS и задержкой внизу. Расставьте кнопки в предпросмотре: перетащите, чтобы переместить, x убирает, + стороны добавляет. Перемещайте панель в редакторе HUD."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "Бонусы лагеря и оставшееся время на экране и напоминание, когда бонусы лагеря заканчиваются."
L["Your camp's bonuses by the icon, always or while you hover it."] = "Бонусы лагеря рядом со значком, всегда или при наведении."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Ваш предел %d.\nСначала выполните задание %s%s|r (%sнавык %d):"
